select account_email, account_password
from ohfifthlane.account_tbl
where account_email = #{accountEmail} and account_password = #{accountPassword}


select account_email from ohfifthlane.account_tbl a 
join ohfifthlane.user_tbl u on a.account_id = u.account_id 
where u.user_name = #{userName} and u.user_ssn_front = #{userSSNFront};
